import math, random

def dist(a, b):
    return math.sqrt(sum((x-y)**2 for x,y in zip(a,b)))

def kmeans(points, k, seed=42):
    random.seed(seed)
    centers = random.sample(points, k)
    for _ in range(20):
        groups = [[] for _ in range(k)]
        for p in points:
            groups[min(range(k), key=lambda i: dist(p, centers[i]))].append(p)
        centers = [[sum(x[d] for x in g)/len(g) for d in range(len(points[0]))]
                   for g in groups]
    return centers

pts = [[1,1],[1,2],[2,1],[8,8],[8,9],[9,8]]
ctrs = kmeans(pts, k=2)
for c in ctrs:
    print([round(v, 2) for v in c])
